/*
 * Hand-written MCP Events helpers. Not generated by Speakeasy: this file is not
 * tracked in .speakeasy/gen.lock, so it survives SDK regeneration.
 */

import {
  createMcpEventsClient,
  McpEventsSource,
  McpResult,
} from "./client.js";
import {
  isPlainObject,
  JSONRPCError,
  mcpErrorFrom,
  McpEventsCodeProfile,
  McpEventsErrorCodes,
  resolveErrorCodes,
} from "./errors.js";

export type McpEventsMethod = "events/list" | "events/subscribe" | "events/unsubscribe";

type MaybePromise<T> = T | Promise<T>;

export type McpEventsHandlerOptions<Ctx = any> = {
  /**
   * Maps the authenticated principal to the Outpost tenant whose events it
   * may subscribe to. Return null, undefined or "" when the principal has no
   * tenant; the request is then rejected with Forbidden.
   */
  resolveTenant: (principal: string, context: Ctx) => MaybePromise<string | null | undefined>;
  /**
   * The topics the principal may discover and subscribe to. When set,
   * `events/list` only returns these topics (an empty list answers with no
   * events, without calling Outpost) and `events/subscribe` rejects any other
   * name with NotFound, the same error as an unknown topic.
   * `events/unsubscribe` is never filtered, so cleanup always works.
   */
  allowedTopics?: ((principal: string, context: Ctx) => MaybePromise<readonly string[]>) | undefined;
  /**
   * JSON-RPC codes for the errors raised locally. Match Outpost's
   * MCP_ERROR_CODES. Defaults to "sketch".
   */
  codes?: McpEventsCodeProfile | McpEventsErrorCodes | undefined;
  /**
   * Called with every failure answered as a generic internal error (Outpost
   * unreachable, unexpected status, resolver errors), for logging. MCP
   * clients never see these details.
   */
  onError?: ((error: unknown, info: { method: McpEventsMethod }) => void) | undefined;
};

export type McpEventsHandlerCallOptions<Ctx = any> = {
  /** Passed to resolveTenant and allowedTopics. */
  context?: Ctx;
  /** Aborts the Outpost call. */
  signal?: AbortSignal | undefined;
};

/**
 * Transport-agnostic `events/*` handlers. Each takes the authenticated
 * principal and the raw MCP params, and resolves to the MCP result or rejects
 * with a JSONRPCError ({code, message, data}) to send back as is.
 */
export type McpEventsHandlers<Ctx = any> = {
  handleList(
    principal: string | null | undefined,
    params: unknown,
    options?: McpEventsHandlerCallOptions<Ctx>,
  ): Promise<McpResult>;
  handleSubscribe(
    principal: string | null | undefined,
    params: unknown,
    options?: McpEventsHandlerCallOptions<Ctx>,
  ): Promise<McpResult>;
  handleUnsubscribe(
    principal: string | null | undefined,
    params: unknown,
    options?: McpEventsHandlerCallOptions<Ctx>,
  ): Promise<McpResult>;
};

/**
 * Builds the `events/list`, `events/subscribe` and `events/unsubscribe`
 * handlers on top of the Outpost MCP endpoints. Authorization is the
 * operator's: requests without a principal or tenant fail with Forbidden.
 */
export function createMcpEventsHandlers<Ctx = any>(
  source: McpEventsSource,
  options: McpEventsHandlerOptions<Ctx>,
): McpEventsHandlers<Ctx> {
  if (typeof options?.resolveTenant !== "function") {
    throw new TypeError("resolveTenant is required");
  }
  const client = createMcpEventsClient(source);
  const codes = resolveErrorCodes(options.codes);
  const { resolveTenant, allowedTopics, onError } = options;

  const forbidden = () => new JSONRPCError(codes.forbidden, "Forbidden");
  const invalidParams = (field: string) =>
    new JSONRPCError(codes.invalidParams, "InvalidParams", { field, reason: "invalid" });

  async function run(
    method: McpEventsMethod,
    fn: () => Promise<McpResult>,
  ): Promise<McpResult> {
    try {
      const result = await fn();
      if (!isPlainObject(result)) {
        throw new TypeError(`${method} result is not an object`);
      }
      return result;
    } catch (err) {
      if (err instanceof JSONRPCError) {
        throw err;
      }
      const mcpError = mcpErrorFrom(err);
      if (mcpError) {
        throw new JSONRPCError(mcpError.code, mcpError.message, mcpError.data);
      }
      if (onError) {
        try {
          onError(err, { method });
        } catch {
          // A logging hook must not change the answer.
        }
      }
      throw new JSONRPCError(codes.internalError, "Internal error");
    }
  }

  async function prepare(
    principal: unknown,
    params: unknown,
    context: Ctx,
  ): Promise<{ principal: string; params: Record<string, unknown>; tenantId: string }> {
    if (typeof principal !== "string" || principal === "") {
      throw forbidden();
    }
    if (params === undefined || params === null) {
      params = {};
    }
    if (!isPlainObject(params)) {
      throw invalidParams("params");
    }
    const tenantId = await resolveTenant(principal, context);
    if (typeof tenantId !== "string" || tenantId === "") {
      throw forbidden();
    }
    return { principal, params, tenantId };
  }

  async function allowlist(principal: string, context: Ctx): Promise<string[] | undefined> {
    if (!allowedTopics) {
      return undefined;
    }
    const topics: unknown = await allowedTopics(principal, context);
    if (!Array.isArray(topics)) {
      throw new TypeError("allowedTopics must return an array of topic names");
    }
    // Topic names never contain commas (the list is sent comma-separated) and
    // are never empty, so such entries can only fail to match; dropping them
    // keeps the allowlist from widening.
    return topics.filter(
      (t): t is string => typeof t === "string" && t !== "" && !t.includes(","),
    );
  }

  return {
    handleList(principal, params, call = {}) {
      return run("events/list", async () => {
        const context = call.context as Ctx;
        const req = await prepare(principal, params, context);
        const cursor = ownProperty(req.params, "cursor");
        if (cursor !== undefined && cursor !== null && typeof cursor !== "string") {
          throw invalidParams("cursor");
        }
        const topics = await allowlist(req.principal, context);
        if (topics && topics.length === 0) {
          return { events: [] };
        }
        return client.listEvents(
          req.tenantId,
          {
            cursor: typeof cursor === "string" ? cursor : undefined,
            topics,
          },
          { signal: call.signal },
        );
      });
    },

    handleSubscribe(principal, params, call = {}) {
      return run("events/subscribe", async () => {
        const context = call.context as Ctx;
        const req = await prepare(principal, params, context);
        const topics = await allowlist(req.principal, context);
        if (topics) {
          for (const name of nameValues(req.params)) {
            if (typeof name === "string" && !topics.includes(name)) {
              throw new JSONRPCError(codes.notFound, "NotFound", { kind: "event" });
            }
          }
        }
        return client.subscribe(
          req.tenantId,
          {
            principal: req.principal,
            params: req.params,
            // Outpost enforces the same list, covering names that are not
            // strings and any client that bypasses this check.
            allowed_topics: topics,
          },
          { signal: call.signal },
        );
      });
    },

    handleUnsubscribe(principal, params, call = {}) {
      return run("events/unsubscribe", async () => {
        const req = await prepare(principal, params, call.context as Ctx);
        return client.unsubscribe(
          req.tenantId,
          { principal: req.principal, params: req.params },
          { signal: call.signal },
        );
      });
    },
  };
}

// Reads only own properties: a "__proto__" member parsed into a params object
// must not supply an inherited "name" that the serialized request lacks.
function ownProperty(obj: Record<string, unknown>, key: string): unknown {
  return Object.prototype.hasOwnProperty.call(obj, key) ? obj[key] : undefined;
}

// Every own member a server could read as `name`. Outpost is written in Go,
// whose JSON decoding matches member names case-insensitively, so
// {"name":"allowed","Name":"hidden"} must not pass as "allowed".
function nameValues(params: Record<string, unknown>): unknown[] {
  return Object.keys(params)
    .filter((key) => key.toLowerCase() === "name")
    .map((key) => params[key]);
}
